	"golive__tip_broadcaster_1": "<b>ASTUCE :</b> merci de diffuser en direct ! Accueillez les gens en leur disant bonjour quand ils rejoignent votre vidéo.",
	"golive__tip_broadcaster_10": "<b>ASTUCE :</b> merci de diffuser en direct sur X ! ≺3",
	"golive__tip_broadcaster_2": "<b>ASTUCE :</b> accueillez les gens en disant leur nom quand ils rejoignent votre vidéo en direct. Ils apprécieront !",
	"golive__tip_broadcaster_3": "<b>ASTUCE :</b> restez bien en direct pendant au moins quelques minutes pour que les gens puissent facilement vous trouver.",
	"golive__tip_broadcaster_4": "\"<b>ASTUCE :</b> demandez à vos spectateurs d'où ils viennent. C'est un super moyen de briser la glace.\"",
	"golive__tip_broadcaster_5": "\"<b>ASTUCE :</b> remerciez les gens de s'être connectés et réagissez à leurs commentaires pour qu'ils continuent à regarder.\"",
	"golive__tip_broadcaster_6": "<b>ASTUCE :</b> si vous perdez votre connexion pendant que vous diffusez en direct, déplacez-vous pour obtenir un meilleur signal.",
	"golive__tip_broadcaster_7": "<b>ASTUCE :</b> demandez aux gens de vous suivre pour être avertis la prochaine fois que vous passez en direct.",
	"golive__tip_broadcaster_8": "<b>ASTUCE :</b> commencez votre vidéo en direct en disant bonjour. Les gens qui la regarderont apprécieront.",
	"golive__tip_broadcaster_9": "\"<b>ASTUCE :</b> remerciez les gens d'avoir regardé votre vidéo avant d'y mettre fin.\"",
	"golive__tip_pre_broadcast_1": "<b>ASTUCE :</b> écrivez un titre avant de passer en direct pour aider les gens à découvrir votre vidéo.",
	"golive__tip_pre_broadcast_2": "<b>ASTUCE :</b> un titre descriptif aide les gens à mieux comprendre le sujet de votre vidéo en direct.",
	"golive__tip_pre_broadcast_3": "\"<b>ASTUCE :</b> besoin d'idées ? Faites visiter un lieu, partagez un talent, ou parlez de quelque chose qui vous intéresse.\"",
	"golive__tip_pre_broadcast_4": "<b>ASTUCE :</b> vérifiez la force du signal de votre téléphone avant de passer en direct.",
	"golive__tip_pre_broadcast_5": "<b>ASTUCE :</b> ajoutez un hashtag à votre titre pour aider les gens à découvrir votre vidéo en direct.",
	"golive__tip_pre_broadcast_6": "\"<b>ASTUCE :</b> pas d'autres astuces pour le moment. Merci de diffuser en direct sur X !\"",
