	"identity_description": "\"Vérifiez votre pièce d'identité officielle pour confirmer votre identité et profiter des fonctionnalités Premium.\"",
	"identity_education_camera_permissions": "Pour vérifier votre identité, nous devons pouvoir accéder à votre appareil photo.",
	"identity_education_cancel": "Ignorer pour le moment",
	"identity_education_conditions": "\"J'accepte que X et Au10tix utilisent des photos de ma pièce d'identité, notamment les données biométriques extraites, ainsi que mon selfie, pour confirmer mon identité et à des fins de sécurité et de protection, notamment pour prévenir l'usurpation d'identité. Au10tix est susceptible de stocker ces données pendant 30 jours maximum. {{}}En savoir plus{{}}\"",
	"identity_education_conditions_age_verification": "\"J'accepte que X et Persona utilisent des photos de ma pièce d'identité et ma photo pour confirmer mon âge. Votre photo ne sera pas stockée. X et xAI pourront conserver les informations relatives à votre âge. {{}}En savoir plus{{}}\"",
	"identity_education_conditions_eea": "\"Dans le cadre de la vérification de mon identité, j'accepte que X transmette à la société Au10tix des photos de ma pièce d'identité, notamment des données biométriques, ainsi que des données personnelles de mon profil.\nJ'accepte également que X stocke pendant une durée maximale de 30 jours les photos de ma pièce d'identité, notamment des données biométriques, et les utilise ainsi que les données de mon profil à des fins de sécurité et de protection, notamment pour prévenir l'usurpation d'identité. {{}}En savoir plus{{}}\"",
	"identity_education_conditions_persona_vendor": "\"J'accepte que X et Persona utilisent des photos de ma pièce d'identité et mon selfie, notamment les données biométriques extraites, pour confirmer mon identité et à des fins de sécurité et de protection, de prévention des fraudes et de paiement. Persona est susceptible de stocker ces données pendant 30 jours maximum. X peut stocker mon nom et mon prénom, mon adresse et une version hachée du numéro de ma pièce d'identité pour toute la durée de mon abonnement au service X Premium. {{}}En savoir plus{{}}\"",
	"identity_education_description": "Ce dont vous aurez besoin :",
	"identity_education_requirement_one": "\"Préparez une pièce d'identité officielle.\"",
	"identity_education_requirement_three": "\"Préparez‑vous à faire un selfie et des photos de votre pièce d'identité.\"",
	"identity_education_requirement_two": "\"Vérifiez que l'appareil photo de votre appareil est accessible et qu'il fonctionne.\"",
