	"payment_funds_insurance_footer_text": "\"Vos dépôts sont détenus par la Cross River Bank, une banque membre de la FDIC, et sont assurés par la FDIC jusqu'à 250 000 $ par personne physique et par personne morale pour tous les comptes de chaque catégorie de propriété détenus à la banque (combinés), y compris les comptes détenus en qualité de représentant.\"",
	"payment_funds_insurance_footer_text_format": "Vos dépôts sont détenus par la Cross River Bank (« la Banque »), membre de la FDIC et sont assurés par la FDIC à hauteur de {amount} par personne physique et par personne morale pour tous les comptes de chaque catégorie de propriété de compte détenus à la Banque (combinés), y compris les comptes détenus à titre de représentant.",
	"payment_funds_insurance_sweep_disclaimer": "\"Les dépôts sont conservés à la Cross River Bank, membre de la FDIC, et dans ﻿d'autres institutions assurées par la FDIC﻿. ﻿Certaines conditions﻿ doivent être remplies pour que la couverture d'assurance des dépôts pass-through s'applique. X Payments LLC n'est pas une banque assurée par la FDIC. La garantie des dépôts ne couvre que la faillite d'une banque assurée.\"",
	"payment_funds_insurance_sweep_presentation": "\"Vos dépôts sont automatiquement inscrits dans le programme Cash Sweep de X, offrant jusqu'à 10 millions de dollars d'assurance FDIC, sous réserve de certaines restrictions. ﻿En savoir plus﻿.\"",
