	"ps__tip_broadcaster_1": "<b>ASTUCE :</b> Merci de diffuser ! Assurez-vous de dire bonjour aux personnes qui arrivent.",
	"ps__tip_broadcaster_11": "<b>ASTUCE :</b> Merci de diffuser sur Periscope ! ≺3",
	"ps__tip_broadcaster_2": "\"<b>ASTUCE :</b> Essayez d'appeler les spectateurs qui arrivent par leur nom ; ils vont êtes ravis !\"",
	"ps__tip_broadcaster_3": "\"<b>ASTUCE :</b> Assurez-vous de diffuser au moins quelques minutes afin qu'il soit plus facile de vous trouver.\"",
	"ps__tip_broadcaster_4": "\"<b>ASTUCE :</b> Demander à vos spectateurs d'où ils sont est une bonne façon de briser la glace.\"",
	"ps__tip_broadcaster_5": "\"<b>ASTUCE :</b> Remerciez vos spectateurs de s'être branchés et répondez à leurs commentaires afin qu'ils continuent de participer.\"",
	"ps__tip_broadcaster_6": "<b>ASTUVE :</b> Si vous perdez la connexion pendant la diffusion, allez quelque part avec un meilleur signal.",
	"ps__tip_broadcaster_7": "\"<b>ASTUCE :</b> Demandez à vos spectateurs de vous suivre afin qu'ils soient notifiés lorsque vous passez en direct.\"",
	"ps__tip_broadcaster_8": "<b>ASTUCE :</b> Démarrez votre diffusion en disant bonjour tout de suite. Les spectateurs de votre rediffusion vont adorer.",
	"ps__tip_broadcaster_9": "\"<b>ASTUCE :</b> Remerciez vos spectateurs d'avoir regardé votre diffusion avant de la terminer.\"",
	"ps__tip_pre_broadcast_1": "<b>ASTUCE :</b> Écrivez un titre avant de commencer votre diffusion pour rencontrer des personnes partageant vos intérêts !",
	"ps__tip_pre_broadcast_2": "<b>ASTUCE :</b> Un titre descriptif permet de comprendre de quoi parle votre diffusion.",
	"ps__tip_pre_broadcast_3": "\"<b>ASTUCE :</b> En manque d'idées ? Faites le guide, partagez un talent, ou parlez d'un sujet qui vous intéresse.\"",
	"ps__tip_pre_broadcast_4": "<b>ASTUCE :</b> Vérifiez que vous avez une bonne couverture téléphonique avant de passer en direct.",
	"ps__tip_pre_broadcast_5": "<b>ASTUCE :</b> partagez vos diffusions sur X pour toucher un plus large public.",
	"ps__tip_pre_broadcast_6": "<b>ASTUCE :</b> Si vous suivez certains de vos abonnés, vous pouvez leur adresser une diffusion privée.",
	"ps__tip_pre_broadcast_8": "<b>ASTUCE :</b> Ajoutez un hashtag pertinent à votre titre pour améliorer la visibilité de votre diffusion.",
	"ps__tip_pre_broadcast_9": "\"<b>ASTUCE :</b> Ce sont toutes les astuces que nous avons pour le moment, merci d'utiliser Periscope !\"",
	"ps__tip_viewer_1": "<b>ASTUCE :</b> Vous êtes un des premiers à arriver, écrivez un commentaire pour dire bonjour !",
	"ps__tip_viewer_2": "<b>ASTUCE :</b> Écrivez un commentaire et faites savoir à <b>%1$s</b> que vous êtes ici !",
	"ps__tip_viewer_3": "\"<b>ASTUCE :</b> Permettez à <b>%1$s</b> de savoir d'où vous regardez !\"",
	"ps__tip_viewer_4": "\"<b>ASTUCE :</b> Dites bonjour pour discuter avec <b>%1$s</b> et d'autres spectateurs.\"",
