	"room_settings_clips": "Clips",
	"room_settings_clips_description": "\"Quand vous faites un clip, les 30 secondes de son qui le précèdent sont enregistrées. \n \nEn tant qu'hôte, vous pouvez supprimer des clips de votre Espace qui ont été faits par d'autres personnes. Toutefois, si vous supprimez un clip de votre Espace, tous les clips de ce même Espace seront supprimés. \n \nSi vous supprimez un Espace que vous aviez enregistré, tous les clips de cet Espace seront aussi supprimés. \n \nTous les clips expirent au bout de 30 jours.\"",
