	"safety_mode_more_info": "\"Qu'est-ce que le Mode Sécurité ?\"",
	"safety_mode_preview_description_more_than_ten": "\"Nous avons signalé plus de 10 comptes à l'origine de potentiels spams ou comportements inappropriés.\"",
	"safety_mode_preview_title": "Limitez les interactions non souhaitées",
	"safety_mode_settings_error": "Impossible de mettre à jour les paramètres du Mode Sécurité.",
	"safety_mode_settings_half_sheet_description_1": "\"Quand nous détectons des réponses, des mentions ou des citations s'apparentant à de potentiels comportements inappropriés ou spams, nous bloquons automatiquement ces comptes de façon temporaire. Contrairement aux blocages manuels, les blocages automatiques ne durent qu'une semaine.\"",
