	"tipjar_input_rationale_kakao_pay": "\"Les personnes enverront leurs dons au lien QR que vous avez saisi ci-dessus.\nEn ajoutant votre lien QR et en acceptant les dons, vous pourriez dévoiler des informations sur vous qui sont partagées sur le service de paiement, notamment votre nom et votre adresse email, entre autres.\n\nVous trouverez le lien QR KakaoPay sur KakaoTalk More > Scanner (en haut à droite) > Code de devise > Icône Presse-papiers. Appuyez sur l'icône pour copier le lien dans votre Presse-papiers, puis collez-le ci-dessus.\"",
	"tipjar_input_rationale_paytm": "Les personnes enverront leurs dons au numéro de mobile associé à Paytm que vous avez saisi ci-dessus. En ajoutant votre numéro de mobile et en acceptant les dons, vous pourriez dévoiler des informations sur vous qui sont partagées sur le service de paiement, notamment votre nom, votre adresse email et votre numéro de téléphone, entre autres.",
